dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ Событие.Ссылка КАК Ссылка, Событие.Филиал КАК Филиал, Событие.Клиент КАК Клиент, Событие.ВидСобытия КАК ВидСобытия, Событие.ДатаПлан КАК ДатаПлан, Событие.ДатаФакт КАК ДатаФакт, Событие.Цель КАК Цель, Событие.Комментарий КАК Комментарий, Событие.ПлановыйИсполнитель КАК ПлановыйИсполнитель, Событие.ФактическийИсполнитель КАК ФактическийИсполнитель ПОМЕСТИТЬ СобытияЗаПериод ИЗ Документ.Событие КАК Событие ГДЕ НЕ Событие.ПометкаУдаления И НЕ(Событие.ДатаФакт = ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) И ЕСТЬNULL(Событие.Основание.ПометкаУдаления, ЛОЖЬ)) {ГДЕ (Событие.Дата МЕЖДУ &ДатаНачала И &ДатаОкончания)} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ЕСТЬNULL(Клиенты.Ссылка, ЗНАЧЕНИЕ(Справочник.Клиенты.ПустаяСсылка)) КАК Клиент, СобытияЗаПериод.Ссылка КАК Событие, ЕСТЬNULL(ВЫБОР КОГДА СобытияЗаПериод.ДатаФакт = ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) И СобытияЗаПериод.ДатаПлан <> ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ, ЛОЖЬ) КАК Плановое, ЕСТЬNULL(ВЫБОР КОГДА СобытияЗаПериод.ДатаФакт <> ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ, ЛОЖЬ) КАК Выполнено, ЕСТЬNULL(ВЫБОР КОГДА СобытияЗаПериод.ДатаПлан <> ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) И (СобытияЗаПериод.ДатаФакт = ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) И НАЧАЛОПЕРИОДА(СобытияЗаПериод.ДатаПлан, ДЕНЬ) < НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ) ИЛИ СобытияЗаПериод.ДатаПлан <> ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) И СобытияЗаПериод.ДатаФакт <> ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) И НАЧАЛОПЕРИОДА(СобытияЗаПериод.ДатаПлан, ДЕНЬ) < НАЧАЛОПЕРИОДА(СобытияЗаПериод.ДатаФакт, ДЕНЬ)) ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ, ЛОЖЬ) КАК Просрочено, ЕСТЬNULL(Клиенты.Статус, ЗНАЧЕНИЕ(Справочник.СтатусыКлиентов.ПустаяСсылка)) КАК СтатусКлиента, СобытияЗаПериод.ВидСобытия КАК ВидСобытия, СобытияЗаПериод.ДатаПлан КАК ДатаПлан, СобытияЗаПериод.ДатаФакт КАК ДатаФакт, СобытияЗаПериод.Комментарий КАК Комментарий, ВЫБОР КОГДА СобытияЗаПериод.Ссылка ЕСТЬ NULL ТОГДА ЛОЖЬ ИНАЧЕ ИСТИНА КОНЕЦ КАК ЕстьСобытие, СобытияЗаПериод.ПлановыйИсполнитель КАК ПлановыйИсполнитель, СобытияЗаПериод.ФактическийИсполнитель КАК ФактическийИсполнитель ПОМЕСТИТЬ СобытияКлиентов ИЗ СобытияЗаПериод КАК СобытияЗаПериод ЛЕВОЕ СОЕДИНЕНИЕ Справочник.Клиенты КАК Клиенты ПО СобытияЗаПериод.Клиент = Клиенты.Ссылка ГДЕ НЕ ЕСТЬNULL(Клиенты.ПометкаУдаления, ЛОЖЬ)
ИНДЕКСИРОВАТЬ ПО Клиент ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ СобытияКлиентов.Клиент КАК Клиент, МАКСИМУМ(СобытияКлиентов.Просрочено) КАК ЕстьПросроченныеСобытия, МАКСИМУМ(СобытияКлиентов.Плановое) КАК ЕстьПлановыеСобытия, МАКСИМУМ(ВЫБОР КОГДА СобытияКлиентов.Плановое И НЕ СобытияКлиентов.Просрочено ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ) КАК ЕстьПлановыеНеПросроченныеСобытия, МАКСИМУМ(СобытияКлиентов.ЕстьСобытие) КАК ЕстьСобытия ПОМЕСТИТЬ СгруппированныеКлиенты ИЗ СобытияКлиентов КАК СобытияКлиентов
СГРУППИРОВАТЬ ПО СобытияКлиентов.Клиент
ИНДЕКСИРОВАТЬ ПО Клиент ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ СгруппированныеКлиенты.Клиент КАК Клиент, СгруппированныеКлиенты.ЕстьПлановыеСобытия КАК ЕстьПлановыеСобытия, СгруппированныеКлиенты.ЕстьПросроченныеСобытия КАК ЕстьПросроченныеСобытия, СгруппированныеКлиенты.ЕстьПлановыеНеПросроченныеСобытия КАК ЕстьПлановыеНеПросроченныеСобытия, СгруппированныеКлиенты.ЕстьСобытия КАК ЕстьСобытия, МАКСИМУМ(ЕСТЬNULL(Заявка.ДатаНачала, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) КАК ДатаПоследнейЗаявки, МАКСИМУМ(ЕСТЬNULL(Продажи.Период, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) КАК ДатаПоследнейПродажи, МАКСИМУМ(ВЫБОР КОГДА Заявка.Ссылка ЕСТЬ NULL ТОГДА ЛОЖЬ ИНАЧЕ ИСТИНА КОНЕЦ) КАК ЕстьЗаявки, МАКСИМУМ(ВЫБОР КОГДА Продажи.Регистратор ЕСТЬ NULL ТОГДА ЛОЖЬ ИНАЧЕ ИСТИНА КОНЕЦ) КАК ЕстьПродажи ПОМЕСТИТЬ КлиентыЗаявкиПродажи ИЗ СгруппированныеКлиенты КАК СгруппированныеКлиенты ЛЕВОЕ СОЕДИНЕНИЕ Документ.Заявка КАК Заявка ПО СгруппированныеКлиенты.Клиент = Заявка.Клиент И (НЕ Заявка.ПометкаУдаления) И (Заявка.Состояние <> ЗНАЧЕНИЕ(Справочник.ВидыСостоянийЗаявок.Отменена)) ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.Продажи КАК Продажи ПО СгруппированныеКлиенты.Клиент = Продажи.Клиент
СГРУППИРОВАТЬ ПО СгруппированныеКлиенты.Клиент, СгруппированныеКлиенты.ЕстьПлановыеСобытия, СгруппированныеКлиенты.ЕстьПросроченныеСобытия, СгруппированныеКлиенты.ЕстьПлановыеНеПросроченныеСобытия, СгруппированныеКлиенты.ЕстьСобытия ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ СобытияКлиентов.Клиент КАК Клиент, СобытияКлиентов.Событие КАК Событие, СобытияКлиентов.Плановое КАК Плановое, СобытияКлиентов.Просрочено КАК Просрочено, СобытияКлиентов.Выполнено КАК Выполнено, СобытияКлиентов.ВидСобытия КАК ВидСобытия, СобытияКлиентов.ДатаПлан КАК ДатаПлан, СобытияКлиентов.ДатаФакт КАК ДатаФакт, СобытияКлиентов.СтатусКлиента КАК СтатусКлиента, КлиентыЗаявкиПродажи.ЕстьПлановыеСобытия КАК ЕстьПлановыеСобытия, КлиентыЗаявкиПродажи.ЕстьПросроченныеСобытия КАК ЕстьПросроченныеСобытия, КлиентыЗаявкиПродажи.ЕстьПлановыеНеПросроченныеСобытия КАК ЕстьПлановыеНеПросроченныеСобытия, КлиентыЗаявкиПродажи.ЕстьСобытия КАК ЕстьСобытия, КлиентыЗаявкиПродажи.ЕстьЗаявки КАК ЕстьЗаявки, КлиентыЗаявкиПродажи.ЕстьПродажи КАК ЕстьПродажи, КлиентыЗаявкиПродажи.ДатаПоследнейЗаявки КАК ДатаПоследнейЗаявки, КлиентыЗаявкиПродажи.ДатаПоследнейПродажи КАК ДатаПоследнейПродажи, СобытияКлиентов.Комментарий КАК Комментарий, КлиентыЗаявкиПродажи.Клиент.Ответственный КАК Ответственный, КлиентыЗаявкиПродажи.Клиент.ОсновнойСотрудник КАК ОсновнойСотрудник, СобытияКлиентов.ПлановыйИсполнитель КАК ПлановыйИсполнитель, СобытияКлиентов.ФактическийИсполнитель КАК ФактическийИсполнитель, ВЫБОР КОГДА СобытияКлиентов.ФактическийИсполнитель <> ЗНАЧЕНИЕ(Справочник.Пользователи.ПустаяСсылка) ТОГДА СобытияКлиентов.ФактическийИсполнитель КОГДА СобытияКлиентов.ПлановыйИсполнитель <> ЗНАЧЕНИЕ(Справочник.Пользователи.ПустаяСсылка) ТОГДА СобытияКлиентов.ПлановыйИсполнитель ИНАЧЕ КлиентыЗаявкиПродажи.Клиент.Ответственный КОНЕЦ КАК Исполнитель ИЗ СобытияКлиентов КАК СобытияКлиентов ЛЕВОЕ СОЕДИНЕНИЕ КлиентыЗаявкиПродажи КАК КлиентыЗаявкиПродажи ПО СобытияКлиентов.Клиент = КлиентыЗаявкиПродажи.Клиент
